; music.asm - title music: small 3-voice player, runs in the raster IRQ
; (music_tick after sound_tick). Song data: src/music_data.asm, generated by
; tools/gen_music.py. One tick = MUS_SPEED frames (a 16th note).
; Voice 1 plays only sparse highlights: while a sound effect runs (snd_dur /
; snd_off <> 0) the player leaves SID voice 1 alone and just keeps counting.
; music_start / music_stop are called from the main program (title.asm).

mus_ptr     = $FC               ; $FC/$FD, used only inside the IRQ

!zone music_start
music_start
        jsr ambient_stop        ; title and world map never play together
        php
        sei
        ldx #2
.v      lda mus_ord_start,x
        sta mus_opos,x
        lda #0
        sta mus_ins,x
        sta mus_note,x
        sta mus_gate,x
        sta mus_wave,x
        lda #1
        sta mus_dur,x
        sta mus_ticks,x         ; first event at the first tick
        jsr mus_next_pat
        dex
        bpl .v
        lda #1
        sta mus_frame
        sta mus_on
        plp
        rts

!zone music_stop
music_stop
        php
        sei
        lda #0
        sta mus_on
        sta SID_BASE+7+4        ; voices 2 and 3 silent at once
        sta SID_BASE+14+4
        lda snd_dur
        ora snd_off
        bne .sfx                ; voice 1 belongs to a running effect
        lda #0
        sta SID_BASE+4
        jsr snd_voice1_setup
.sfx    plp
        rts

; X = voice: next pattern from its order list ($FE pos = jump to pos).
!zone mus_next_pat
mus_next_pat
.again  ldy mus_opos,x
        lda mus_order,y
        cmp #$FE
        bne .pat
        lda mus_order+1,y
        sta mus_opos,x
        jmp .again
.pat    tay
        lda mus_pat_lo,y
        sta mus_plo,x
        lda mus_pat_hi,y
        sta mus_phi,x
        lda #0
        sta mus_ppos,x
        inc mus_opos,x
        rts

!zone music_tick
music_tick
        lda mus_on
        bne .on
        rts
.on     dec mus_frame
        bne .fx
        lda #MUS_SPEED
        sta mus_frame
        ldx #2
.t      dec mus_ticks,x
        bne .tn
        jsr mus_read
.tn     dex
        bpl .t
.fx     ldx #2
.f      jsr mus_fx
        dex
        bpl .f
        rts

; Carry set: voice X may not touch the SID now (voice 1 during an effect).
!zone mus_busy
mus_busy
        cpx #0
        bne .free
        lda snd_dur
        ora snd_off
        beq .free
        sec
        rts
.free   clc
        rts

; X = voice, A = note: write its frequency.
!zone mus_setfreq
mus_setfreq
        tay
        lda mus_flo,y
        sta mus_tmp
        lda mus_fhi,y
        ldy mus_sid,x
        sta SID_BASE+1,y
        lda mus_tmp
        sta SID_BASE,y
        rts

; X = voice: read events up to the next note or rest and start it.
!zone mus_read
mus_read
        lda mus_plo,x
        sta mus_ptr
        lda mus_phi,x
        sta mus_ptr+1
        ldy mus_ppos,x
.l      lda (mus_ptr),y
        iny
        cmp #$FF
        bne .noend
        jsr mus_next_pat        ; end of pattern: continue with the next one
        lda mus_plo,x
        sta mus_ptr
        lda mus_phi,x
        sta mus_ptr+1
        ldy #0
        beq .l
.noend  cmp #$A0
        bcc .nins
        and #$1F
        sta mus_ins,x
        jmp .l
.nins   cmp #$80
        bcc .note
        and #$1F
        sta mus_dur,x
        jmp .l
.note   sta mus_note,x
        tya
        sta mus_ppos,x
        lda mus_dur,x
        sta mus_ticks,x
        lda #$FF
        sta mus_fcnt,x
        sta mus_arpc,x
        lda mus_note,x
        bne .play
        lda #0                  ; rest: gate off, release
        sta mus_gate,x
        jsr mus_busy
        bcs .done
        ldy mus_sid,x
        lda mus_wave,x
        sta SID_BASE+4,y
.done   rts
.play   ldy mus_ins,x
        lda ins_wave2,y
        sta mus_wave,x
        lda ins_pw,y
        sta mus_pwhi,x
        lda #0
        sta mus_pwlo,x
        sta mus_pwdir,x
        lda #1
        sta mus_gate,x
        jsr mus_busy
        bcs .done
        stx mus_x
        lda mus_ins,x
        pha
        lda mus_sid,x
        tay
        pla
        tax                     ; X = instrument, Y = SID register offset
        lda #0
        sta SID_BASE+4,y        ; gate off, so the envelope restarts
        sta SID_BASE+2,y
        lda ins_ad,x
        sta SID_BASE+5,y
        lda ins_sr,x
        sta SID_BASE+6,y
        lda ins_pw,x
        sta SID_BASE+3,y
        lda ins_wave1,x
        ora #1
        sta SID_BASE+4,y
        ldx mus_x
        lda mus_note,x
        jmp mus_setfreq

; X = voice: per-frame work (wave switch, arpeggio, pulse sweep, gate off).
!zone mus_fx
mus_fx
        inc mus_fcnt,x
        lda mus_gate,x
        beq .rts
        jsr mus_busy
        bcs .rts
        lda mus_frame           ; last frame of the note: gate off, so the
        cmp #1                  ; next one retriggers cleanly
        bne .wave
        lda mus_ticks,x
        cmp #1
        bne .wave
        lda #0
        sta mus_gate,x
        ldy mus_sid,x
        lda mus_wave,x
        sta SID_BASE+4,y
.rts    rts
.wave   lda mus_fcnt,x
        cmp #1
        bne .arp
        ldy mus_sid,x           ; second frame: main waveform
        lda mus_wave,x
        ora #1
        sta SID_BASE+4,y
.arp    ldy mus_ins,x
        lda ins_arp,y
        beq .pwm
        tay
        inc mus_arpc,x
        lda mus_arpc,x
        cmp #3
        bcc .ai
        lda #0
        sta mus_arpc,x
.ai     clc
        adc mus_arp_base,y
        tay
        lda mus_arp_tab,y
        clc
        adc mus_note,x
        jsr mus_setfreq
.pwm    ldy mus_ins,x
        lda ins_pwm,y
        beq .rts
        lda mus_pwdir,x
        bne .down
        clc
        lda mus_pwlo,x
        adc #MUS_PWM_STEP
        sta mus_pwlo,x
        lda mus_pwhi,x
        adc #0
        sta mus_pwhi,x
        cmp #$0E
        bcc .wr
        inc mus_pwdir,x
        bne .wr
.down   sec
        lda mus_pwlo,x
        sbc #MUS_PWM_STEP
        sta mus_pwlo,x
        lda mus_pwhi,x
        sbc #0
        sta mus_pwhi,x
        cmp #$03
        bcs .wr
        dec mus_pwdir,x
.wr     ldy mus_sid,x
        lda mus_pwlo,x
        sta SID_BASE+2,y
        lda mus_pwhi,x
        sta SID_BASE+3,y
        rts

MUS_PWM_STEP = $28

mus_sid     !byte 0, 7, 14      ; SID register offset per voice
mus_on      !byte 0
mus_frame   !byte 0
mus_tmp     !byte 0
mus_x       !byte 0
mus_opos    !fill 3
mus_plo     !fill 3
mus_phi     !fill 3
mus_ppos    !fill 3
mus_ticks   !fill 3
mus_dur     !fill 3
mus_ins     !fill 3
mus_note    !fill 3
mus_gate    !fill 3
mus_wave    !fill 3
mus_fcnt    !fill 3
mus_arpc    !fill 3
mus_pwlo    !fill 3
mus_pwhi    !fill 3
mus_pwdir   !fill 3

!source "src/music_data.asm"
